#include "../guest/Desktop.h"
#include "../src/microvm/gui/WindowBridge.h"
#include <array>
#include <cstring>
#include <iostream>
#include <memory>
#include <stdexcept>
#include <vector>
namespace d=guardian::desktop;namespace p=guardian::presentation;namespace w=av::microvm::window_session;
namespace {
unsigned checks=0;void Check(bool yes,const char* why){++checks;if(!yes)throw std::runtime_error(why);}
d::Frame Metadata(){d::Frame f;f.count=1;auto& a=f.windows[0];a.handle=10;a.pid=1;a.tid=2;a.flags=1;a.bounds=a.client={10,20,30,40};a.title[0]='A';return f;}
struct Client {w::Bridge& bridge;uint64_t sequence=0,frame=0,session=77;bool Call(p::Packet& packet,const uint32_t* pixels=nullptr){packet.boot=1;packet.session=session;packet.sequence=++sequence;packet.frameNumber=frame;return bridge.Exchange(packet,pixels,sequence*1000000);}
    void Present(const d::Frame& metadata){p::Packet b;b.operation=p::Operation::Begin;b.frame=metadata;++frame;Check(Call(b),"Begin frame");for(uint32_t i=0;i<metadata.count;++i){const auto& info=metadata.windows[i];if(info.parent||!(info.flags&1))continue;std::vector<uint32_t> pixels(size_t(info.client.right-info.client.left)*size_t(info.client.bottom-info.client.top),0xFF123456);p::Packet tile;tile.operation=p::Operation::Surface;tile.window=info.handle;tile.width=uint32_t(info.client.right-info.client.left);tile.height=uint32_t(info.client.bottom-info.client.top);tile.stride=tile.width*4;tile.pixelBytes=tile.width*tile.height*4;Check(Call(tile,pixels.data()),"Window pixels");}p::Packet commit;commit.operation=p::Operation::Commit;Check(Call(commit),"Commit frame");}
};
void Protocol(){
    unsigned displayed=0;p::Event input;w::Bridge bridge(1,77,{[&]{auto e=input;input={};return e;},[&](const w::Frame& f){++displayed;Check(f.session==77&&f.images.size()==f.metadata.count,"Atomic display callback");}});Client c{bridge};c.Present(Metadata());Check(displayed==1,"One committed frame");
    p::Packet replay;replay.boot=1;replay.session=77;replay.sequence=c.sequence;Check(!bridge.Exchange(replay,nullptr,c.sequence*1000000),"Replay refused");
    input.session=77;input.window=10;input.kind=p::Kind::KeyDown;input.key='A';input.scan=30;p::Packet poll;poll.operation=p::Operation::Poll;Check(c.Call(poll)&&!poll.status&&poll.event.key=='A',"Targeted input");input=poll.event;input.window=999;poll={};poll.operation=p::Operation::Poll;Check(c.Call(poll)&&poll.status==1,"Deleted/foreign target dropped");
    c.Present({});p::Packet finish;finish.operation=p::Operation::Finish;finish.inputs=1;Check(c.Call(finish)&&bridge.Completed(),"Finish without live windows");Check(!c.Call(finish),"Completed channel sealed");
    for(unsigned bad=0;bad<8;++bad){w::Bridge b(1,77);Client q{b};auto meta=Metadata();p::Packet packet;packet.operation=p::Operation::Begin;packet.frame=meta;q.frame=1;
        if(bad==0)packet.frame.count=33;else if(bad==1)packet.frame.windows[0].title[0]=0xD800;else if(bad==2)packet.frame.windows[0].client.right=2000;else if(bad==3)packet.frame.windows[0].parent=10;else if(bad==4)q.session=88;else if(bad==5)packet.status=1;else if(bad==6)packet.bytes=1;else packet.frame.reserved=1;
        Check(!q.Call(packet),"Malformed frame envelope rejected");}
    w::Bridge missing(1,77);Client m{missing};p::Packet begin;begin.operation=p::Operation::Begin;begin.frame=Metadata();m.frame=1;Check(m.Call(begin),"Missing tile begin");p::Packet commit;commit.operation=p::Operation::Commit;Check(!m.Call(commit),"Missing tile refused");
    w::Bridge resurrect(1,77);Client r{resurrect};r.Present(Metadata());r.Present({});begin={};begin.operation=p::Operation::Begin;begin.frame=Metadata();++r.frame;Check(!r.Call(begin),"Retired identifier refused");
    w::Bridge foreign(1,77,{[]{p::Event e;e.session=88;e.window=10;e.kind=p::Kind::Close;return e;},{}});Client f{foreign};f.Present(Metadata());poll={};poll.operation=p::Operation::Poll;Check(!f.Call(poll),"Foreign session input refused");
    auto quota=Metadata();quota.count=8;for(uint32_t i=0;i<8;++i){quota.windows[i]=quota.windows[0];quota.windows[i].handle=10+i;quota.windows[i].bounds=quota.windows[i].client={0,0,1280,720};}Check(!w::ValidMetadata(quota),"Aggregate backing quota");
    for(const uint32_t dpi:{96u,120u,144u,192u,240u})for(int32_t n=-1000;n<1000;n+=17)Check(p::Logical(p::Physical(n,dpi),dpi)==n,"DPI roundtrip");
}
void Guest(){
    using namespace guardian;auto memory=std::make_unique<memory::Manager>();auto processes=std::make_unique<processes::Manager>();auto scheduler=std::make_unique<threads::Scheduler>();std::vector<uint8_t> ram(16u<<20);const abi::MemoryRegion map[]{{0,0x100000,abi::MemoryKind::Reserved,0,0},{0x100000,ram.size()-0x100000,abi::MemoryKind::Available,0,0}};Check(memory->physical.Initialize(uint64_t(ram.data()),ram.size(),map,2),"Physical initialization");processes->Configure(*memory,*scheduler);processes::Token token;token.user=100;token.primaryGroup=10;uint32_t pid=0;Check(!processes->CreateRoot(token,pid),"Guest process");const auto tid=scheduler->CreateThread();uint64_t handle=0;Check(!processes->Attach(pid,tid,handle),"Guest thread");auto state=std::make_unique<d::State>();d::Core core;core.Initialize(*processes,*scheduler,*state);const uint64_t now=1000000;
    auto create=[&](d::Rect bounds,uint64_t parent,uint32_t style,uint32_t color){d::Request r;r.op=d::Op::Create;r.window.style=style;r.window.bounds=bounds;r.other=parent;r.value=color;r.window.title[0]='T';Check(!core.Execute(pid,tid,now,r),"Create guest window");return r.handle;};
    const auto first=create({-20,-10,100,90},0,0x10000000,0x112233);const auto second=create({0,0,120,100},0,0x10000000,0x445566);const auto child=create({10,10,30,30},first,0x50000000,0x778899);
    std::vector<uint32_t> pixels(d::PixelCount+2,0xDEADBEEF);uint32_t width=0,height=0;Check(core.RenderWindow(first,pixels.data()+1,d::PixelCount,width,height)&&width==120&&height==100,"Offscreen independent surface");Check(pixels[1+50*width+50]==0xFF112233&&pixels[1+15*width+15]==0xFF778899,"Unoccluded root and child pixels");Check(pixels.front()==0xDEADBEEF&&pixels.back()==0xDEADBEEF,"Surface guard bytes");Check(core.RenderWindow(second,pixels.data()+1,d::PixelCount,width,height)&&pixels[1+50*width+50]==0xFF445566,"Overlapping root stays separate");Check(!core.RenderWindow(child,pixels.data()+1,d::PixelCount,width,height),"Child not independent root");Check(!core.RenderWindow(first,pixels.data()+1,4,width,height),"Short surface rejected");
    auto drain=[&]{for(unsigned n=0;n<128;++n){d::Request r;r.op=d::Op::Poll;r.flags=1;Check(!core.Execute(pid,tid,now,r),"Read guest message");if(!r.value)return;if(r.message.id==15){r.op=d::Op::BeginPaint;r.handle=r.message.window;Check(!core.Execute(pid,tid,now,r),"Begin paint");r.op=d::Op::EndPaint;Check(!core.Execute(pid,tid,now,r),"End paint");}}throw std::runtime_error("Drain failed");};drain();
    p::Event e;e.session=77;e.window=first;e.kind=p::Kind::Button;e.x=15;e.y=15;e.buttons=1;Check(!core.InjectWindow(e,77,now)&&core.Metadata().focus==child,"Input routed to child of addressed root");drain();e={};e.session=77;e.window=second;e.kind=p::Kind::Focus;Check(!core.InjectWindow(e,77,now)&&core.Metadata().focus==second,"Independent window focus");drain();e.window=first;e.kind=p::Kind::Blur;Check(!core.InjectWindow(e,77,now)&&core.Metadata().focus==second,"Stale blur cannot clear other root");e.window=second;e.kind=p::Kind::Close;Check(core.InjectWindow(e,88,now)==87,"Guest rejects foreign session");Check(!core.InjectWindow(e,77,now),"Targeted close");d::Request message;message.op=d::Op::Poll;message.flags=1;Check(!core.Execute(pid,tid,now,message)&&message.message.id==0x10&&message.message.window==second,"Close routed exactly");
    e.kind=p::Kind::Geometry;e.bounds={200,100,340,220};Check(!core.InjectWindow(e,77,now),"Host resize/move applied");d::Request query;query.op=d::Op::Query;query.handle=second;Check(!core.Execute(pid,tid,now,query)&&query.window.bounds.left==200&&query.window.client.right-query.window.client.left==140,"Guest geometry matches");drain();query.op=d::Op::Style;query.value=query.window.style|0x08000000;Check(!core.Execute(pid,tid,now,query),"Disable owner");e={};e.session=77;e.window=second;e.kind=p::Kind::KeyDown;e.key='A';Check(core.InjectWindow(e,77,now)==5,"Disabled window input refused");core.Exit(pid);Check(core.Clean(),"Guest resources reclaimed");
}
}
int main(){try{Protocol();Guest();std::cout<<checks<<" window protocol, quota, session, independent raster, targeted input, geometry and DPI checks PASS\n";return 0;}catch(const std::exception& e){std::cerr<<e.what()<<'\n';return 1;}}
